import numpy as np
c = np.load('/tmp/curve.npy')
c = c[np.argsort(c[:,0])]
m, chi = c[:,0], np.log10(c[:,1])

# normalize coords for RDP
X = (m - m.min())/(m.max()-m.min())
Y = (chi - chi.min())/(chi.max()-chi.min())

def rdp_indices(X, Y, n_target):
    import heapq
    keep = {0, len(X)-1}
    def maxdev(i, j):
        if j <= i+1: return (-1, -1)
        xs, ys = X[i:j+1], Y[i:j+1]
        dx, dy = X[j]-X[i], Y[j]-Y[i]
        L = np.hypot(dx, dy)
        if L == 0:
            d = np.hypot(xs-X[i], ys-Y[i])
        else:
            d = np.abs(dy*(xs-X[i]) - dx*(ys-Y[i]))/L
        k = int(np.argmax(d))
        return (d[k], i+k)
    h = []
    d, k = maxdev(0, len(X)-1)
    if k >= 0: heapq.heappush(h, (-d, 0, len(X)-1, k))
    while h and len(keep) < n_target:
        negd, i, j, k = heapq.heappop(h)
        keep.add(k)
        for a, b in ((i, k), (k, j)):
            d2, k2 = maxdev(a, b)
            if k2 >= 0: heapq.heappush(h, (-d2, a, b, k2))
    return sorted(keep)

idx = rdp_indices(X, Y, 100)
mm = m[idx]; cc = 10**chi[idx]
# rescale to rho=0.45
cc = cc*np.sqrt(0.3/0.45)
print(len(idx))
print('chi range after rescale', cc.min(), cc.max())
import json
pts = [[float(f'{a:.6g}'), float(f'{b:.5g}')] for a,b in zip(mm,cc)]
json.dump(pts, open('/tmp/pts.json','w'))
for i in range(0,len(pts),10): print(pts[i])
